					height: 100%;

					path {
						fill: var(--color-bright-green-50);
					}
				}
			}

			// first row only: fade the cell outline via gradient instead of a flat fill
			&:nth-child(-n + 7 of .cell-wrapper) {
				.cell-outline :deep(svg) path {
					fill: url(#cell-outline-gradient);
				}
			}

			.cell-1-content {
				position: absolute;
				inset: 0;

				z-index: 2;
				padding: rs(20, 20);

				display: flex;
				flex-direction: column;
				justify-content: space-between;

				color: var(--color-deep-green-500);

				> span:first-child {
					opacity: 0.5;
					max-width: rs(42, 42);
				}

				> span:last-child {
					max-width: rs(64, 64);
				}

				@include max-width($sm) {
					display: none;
				}
			}

			.cell-2-content {
				position: absolute;
				inset: 0;

				z-index: 2;
				padding: rs(10, 10);

				display: flex;
				flex-direction: column;
				justify-content: space-between;

				color: var(--color-deep-green-500);

				.function-bg {
					background-color: var(--color-bright-green-500);

					border-radius: rs(15, 4);
					padding: rs(5, 5);

					display: flex;
					justify-content: center;

					width: fit-content;
					opacity: 0;

					:deep(span) {
						font-size: rs(8, 8);
					}
