const shaders = ['see', 'test', 'act']
const shaderName = computed(() => shaders[props.index] || 'see')

const el = ref(null)
const context = inject('pageContext')

let resizeObserver = null

const setup = () => {
	const topContainer = el.value?.querySelector('.top-container')
