	context.$page.loader.loaded.then(() => setup())
	if (screen.touch) return
	el.value.addEventListener('mouseenter', onEnter)
	el.value.addEventListener('mousemove', onMove)
	el.value.addEventListener('mouseleave', onLeave)
})
