	updatePictos()

	scrollTrigger = ScrollTrigger.create({
		trigger: el.value,
		start: 'top 80%',
		once: true,
		onEnter: () => {
			hasAnimated.value = true
			gsap.fromTo(
				animateRefs,
				{ scale: 0 },
				{
					scale: 1,
					duration: 1.0,
					ease: 'elastic.out',
					stagger: (i) => Math.pow(i * 0.04, 6),
