		flex-direction: column;
		align-items: center;

		text-align: center;

		pointer-events: none;

		color: var(--color-bright-green-500);

		display: flex;
		flex-direction: column;
		gap: rs(12, 12);

		.description {
			max-width: 40%;
		}

		.title {
			font-size: rs(170, 112);
			margin-top: rs(96, 64);
			margin-bottom: rs(36, 18);
		}
	}

	@supports (corner-shape: superellipse(1.5)) {
		& {
			border-radius: rs(28, 20);
			corner-shape: superellipse(1.5);
		}
	}
}
</style>
